package br.com.confirmacao.auth.api;import br.com.confirmacao.auth.application.AuthenticationResult;import br.com.confirmacao.user.domain.UserRole;import java.util.UUID;public record LoginResponse(String accessToken,String tokenType,long expiresIn,UUID userId,UUID professionalId,String name,UserRole role){public static LoginResponse from(AuthenticationResult r){var u=r.user();return new LoginResponse(r.accessToken(),"Bearer",r.expiresIn(),u.getId(),u.getProfessional()==null?null:u.getProfessional().getId(),u.getName(),u.getRole());}}
